import OpenAI from "openai";

import Write from "./tools/Write.ts";
import Read from "./tools/Read.ts";
import ListDirectory from "./tools/ListDirectory.ts";
import Http from "./tools/Http.ts";
import { config } from "process";

const client = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY,
});

const modelList = [
    "gpt-5.6-sol",
    "gpt-5.6-terra",
    "gpt-5.6-luna",
];

const tools = [
    {
        type: "function",
        name: "Write",
        // description: "Writes content to a file",
        parameters: {
            type: "object",
            properties: {
                path: { type: "string" },
                content: { type: "string" },
                overwrite: { type: "boolean" },
                read_hash: { type: "string" },
            },
            required: ["path", "content", "read_hash"],
        },
        exec_handler: async function ({ path, content, overwrite, read_hash }) {
            return await Write({ path, content, overwrite, read_hash });
        },
    },
    {
        type: "function",
        name: "Read",
        // description: "Reads content from a file",
        parameters: {
            type: "object",
            properties: {
                path: { type: "string" },
            },
            required: ["path",],
        },
        exec_handler: async function ({ path, }) {
            return await Read({ path, });
        },
    },
    {
        type: "function",
        name: "Http",
        parameters: {
            type: "object",
            properties: {
                url: { type: "string" },
            },
            required: ["url",],
        },
        exec_handler: async function ({ url, }) {
            return await Http({ url, });
        },
    },
    {
        type: "function",
        name: "ListDirectory",
        parameters: {
            type: "object",
            properties: {
                directory: { type: "string" },
            },
            required: ["directory",],
        },
        exec_handler: async function ({ directory, }) {
            return await ListDirectory({ directory, });
        },
    },
];

function getTool(name) {
    return tools.find(tool => tool.name === name);
}

function runTool(name, args) {
    const tool = getTool(name);
    if (!tool) {
        throw new Error(`Tool not found: ${name}`);
    }
    return tool.exec_handler(args);
}

function saveData(data, filename = "data.json") {
    // Implement the logic to save data
    try {
        // Example: save data to a file
        const fs = require('fs');
        fs.writeFileSync(filename, JSON.stringify(data, null, 2));
    } catch (error) {
        console.error('Failed to save data:', error);
    }
}

function readData(filename = "data.json") {
    try {
        const fs = require('fs');
        const data = fs.readFileSync(filename, 'utf-8');
        return JSON.parse(data);
    } catch (error) {
        console.error('Failed to read data:', error);
        return null;
    }
}

async function main() {
    const configData = readData();

    if (!configData) {
        configData = { responseIds: [] };
        saveData(configData);
    }

    if (!configData.requestResponses) {
        configData.requestResponses = [];
        saveData(configData);
    }

    if (!configData.toolCallResponse) {
        configData.toolCallResponse = {};
        saveData(configData);
    }

    var request = {
        model: modelList[1],
        tools: tools,
        previous_response_id: configData.lastResponseId,
    };

    if (configData.lastToolCallIds) {
        // const toolResult = {
        //     type: "function_call_output",
        //     call_id: configData.lastToolCallId,
        //     output: JSON.stringify({
        //         temperature: 22,
        //         condition: "Sunny",
        //     }),
        // };

        // const toolData = JSON.stringify(configData.toolCallResponse[configData.lastToolCallIds]);

        // console.log(`toolData: ${toolData}`);

        // const toolResult = {
        //     type: "function_call_output",
        //     call_id: configData.lastToolCallId,
        //     output: toolData,
        // };

        // request.input = [toolResult];

        request.input = configData.lastToolCallIds.map(callId => ({
            type: "function_call_output",
            call_id: callId,
            output: JSON.stringify(configData.toolCallResponse[callId]),
        }));

        console.log(`request.input: ${JSON.stringify(request.input)}`);
    } else {
        request.input = `
        Find all the current tool code in the current directory.
    `;
    }

    const responses = await client.responses.create(request);


    console.log("response:");
    console.dir(responses, { depth: null });

    console.log("Done");

    configData.lastResponseId = responses.id;
    configData.lastToolCallIds = [];

    var loopAgain = false;

    for (var response of responses.output) {
        if (response.type === 'message') {
            console.log(`RESPONSE: ${JSON.stringify(response.content)}`);

            const status = response.status;
            const phase = response.phase;

            console.log(`status: ${status}, phase: ${phase}`);

            if (status === 'completed' && phase === 'final_answer') {
                loopAgain = false;
                configData.lastResponseId = null;
            }
        } else if (response.type === 'function_call') {
            loopAgain = true;

            console.log(`Executing tool: ${response.name}`);
            console.log(`Response ID: ${response.id}`);
            console.log(`type: ${response.type}`);
            console.log(`arguments: ${JSON.stringify(response.arguments)}`);

            var tool = null;
            for (var t of tools) {
                console.log(`Matching tool: ${t.name} against ${response.name}`);
                if (t.name === response.name) {
                    console.log("Found matching tool");
                    console.log(`exec_handler: ${t.exec_handler}`);
                    console.log(`tool: ${JSON.stringify(t)}`);
                    tool = t;
                    break;
                }
            }

            if (tool && tool.exec_handler) {
                console.log(`Executing handler for tool: ${response.name}`);
                console.log(`response: ${JSON.stringify(response)}`);

                const callId = response.call_id;

                const toolArguments = JSON.parse(response.arguments);

                console.log(`toolArguments: ${JSON.stringify(toolArguments)}`);

                const toolResponse = await tool.exec_handler(toolArguments);

                configData.toolCallResponse[callId] = {
                    toolArguments: toolArguments,
                    toolResponse: toolResponse,
                };

                configData.lastToolCallIds.push(callId);

                saveData(configData);
            } else {
                console.error(`No exec_handler found for tool: ${response.name}`);
            }
        }
    }

    saveData(configData);
}

main().catch(console.error);

import { spawn } from "node:child_process";

/** The result produced by {@link executeCommand}. */
export interface ExecuteCommandResult {
  /** The process exit code. A zero value conventionally indicates success. */
  exitCode: number;
  /** Data written by the command to standard output. */
  stdout: string;
  /** Data written by the command to standard error. */
  stderr: string;
}

/**
 * Runs a Bash command and collects its output.
 *
 * `parameters` are exposed to the Bash command as positional parameters:
 * `parameters[0]` is `$1`, `parameters[1]` is `$2`, and so on. For example:
 *
 * ```ts
 * await executeCommand('printf "%s\\n" "$1"', ['hello']);
 * ```
 *
 * @param command Bash source to execute.
 * @param parameters Values to pass as Bash positional parameters.
 * @throws If Bash cannot be started, or if it is terminated by a signal before
 * producing an exit code.
 */
export function executeCommand(
  command: string,
  parameters: readonly string[] = [],
): Promise<ExecuteCommandResult> {
  return new Promise((resolve, reject) => {
    // The `--` supplies $0 to `bash -c`; this prevents the first user-provided
    // parameter from being consumed as $0. Passing an argument array (rather
    // than constructing a shell string) preserves each parameter verbatim.
    const child = spawn("bash", ["-c", command, "--", ...parameters], {
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let spawnError: Error | undefined;

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk: string) => {
      stderr += chunk;
    });

    child.once("error", (error) => {
      spawnError = error;
    });

    child.once("close", (exitCode, signal) => {
      if (spawnError) {
        reject(spawnError);
      } else if (exitCode === null) {
        reject(new Error(`Bash was terminated by signal ${signal ?? "unknown"}`));
      } else {
        resolve({ exitCode, stdout, stderr });
      }
    });
  });
}

export default interface HttpResult {
  response: Response;
  body: string;
}

export default interface HttpOption {
  url: string,
}

/** Calls a URL and returns both the HTTP response and its text body. */
export default async function http({ url }: HttpOption): Promise<HttpResult> {
  const response = await fetch(url);
  const body = await response.text();

  return { response, body };
}

import { readdir } from "node:fs/promises";
import type { Dirent } from "node:fs";

export default interface ListDirectoryOptions {
    directory: string;
}

export default interface ListDirectoryResponse {
  name: string;
  parentPath: string;
  path: string;
}
/** Lists a directory. Each returned entry may be either a file or a directory. */
export default async function listDirectory({ directory }: ListDirectoryOptions): Promise<ListDirectoryResponse[]> {
  console.log(`Listing directory: ${JSON.stringify(directory)}`);

  const readResults = await readdir(directory, { withFileTypes: true });

  console.log(`Read results: ${JSON.stringify(readResults)}`);

  return readResults.map((dirent) => ({
    name: dirent.name,
    parentPath: directory,
    path: `${directory}/${dirent.name}`,
  }));
}

import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";

export interface ReadOptions {
  path: string;
  /** SHA-256 hash of the version of the file the caller expects to read. */
  read_hash: string;
}

export interface ReadResult {
  content: string;
  read_hash: string;
}

/**
 * Reads a UTF-8 file only when its contents match the caller's expected hash.
 *
 * The hash is calculated from the same bytes returned to the caller, so a
 * change between a separate check and read cannot result in unchecked content.
 */
export async function Read({ path }: ReadOptions): Promise<ReadResult> {
  const bytes = await readFile(path);
  const actualHash = createHash("sha256").update(bytes).digest("hex");

  return {
    content: bytes.toString("utf8"),
    read_hash: actualHash,
  };
}

export default Read;

import { createHash, timingSafeEqual } from "node:crypto";
import { open } from "node:fs/promises";


import { access } from "node:fs/promises";
import { constants } from "node:fs";

async function fileExists(path: string): Promise<boolean> {
  try {
    await access(path, constants.F_OK);
    return true;
  } catch {
    return false;
  }
}

export default interface WriteOption {
    path: string;
    content: string;
    overwrite: boolean;
    read_hash: string;
}

/**  * Overwrites a file only when its current SHA-256 hash matches `read_hash`.  */
export default async function Write({ path, content, overwrite, read_hash, }: WriteOption): Promise<void> {
    try {
        // Usage
        if (await fileExists(path)) {
            if (!overwrite) {
                throw new Error("overwrite must be true");
            } 

            if ((typeof read_hash !== "string" || read_hash.trim() === "")) {
                throw new TypeError("read_hash is required");
            }

            console.log("File exists");
            const expectedHash = read_hash.trim().toLowerCase();
            if (!/^[a-f0-9]{64}$/.test(expectedHash)) {
                throw new TypeError("read_hash must be a SHA-256 hash encoded as 64 hexadecimal characters");
            } 

            try {
                const file = await open(path, "r+");
                try {
                    const currentContent = await file.readFile();
                    const currentHash = createHash("sha256").update(currentContent).digest("hex");
                    const hashesMatch = timingSafeEqual(Buffer.from(currentHash, "hex"), Buffer.from(expectedHash, "hex"),);
                    if (!hashesMatch) {
                        throw new Error("File has changed since it was read;  refusing to overwrite it");
                    }            
                } finally {
                    if (file) {
                        await file.close();
                    }
                }
            } catch (err) {
                throw err;
            }
        }

        const file = await open(path, "w");
        try {
            if (!file) {
                throw new Error("File handle is not available");
            }

            await file.truncate(0);
            await file.writeFile(content, { encoding: "utf8" });
        } finally {
            if (file) {
                await file.close();
            }
        }
    } catch (err) {
        throw err;
    }
}

