export default async function Git(options: GitOptions): Promise<GitCommandResult> {
  validateCwd(options.cwd);

  switch (options.action) {
    case "list":
      return runGit(["status", "--short", "--branch"], options.cwd);

    case "stage": {
      const paths = options.paths ?? [];
      if (options.all && paths.length > 0) {
        throw new TypeError("Specify either paths or all: true, not both.");
      }
      if (options.all) {
        return runGit(["add", "--all"], options.cwd);
      }
      if (paths.length === 0) {
        throw new TypeError("stage requires at least one path or all: true.");
      }

      for (const path of paths) {
        validatePath(path);
      }
      // `--` prevents a path such as "--intent-to-add" from being interpreted
      // as a Git option.
      return runGit(["add", "--", ...paths], options.cwd);
    }

    case "commit":
      if (typeof options.message !== "string" || options.message.trim() === "") {
        throw new TypeError("commit requires a non-empty message.");
      }
      return runGit(["commit", "-m", options.message], options.cwd);
  }
}

function validateCwd(cwd: string | undefined): void {
  if (cwd !== undefined && (typeof cwd !== "string" || cwd.length === 0)) {
    throw new TypeError("cwd must be a non-empty string when provided.");
  }
}

function validatePath(path: string): void {
  if (typeof path !== "string" || path.length === 0) {
    throw new TypeError("Each path must be a non-empty string.");
  }
  if (path.includes("\0")) {
    throw new TypeError("Paths cannot contain NUL characters.");
  }
}

function runGit(command: string[], cwd?: string): Promise<GitCommandResult> {
  return new Promise((resolve, reject) => {
    const child = spawn("git", command, {
      cwd,
      stdio: ["ignore", "pipe", "pipe"],
    });

    let stdout = "";
    let stderr = "";
    let spawnError: Error | undefined;

    child.stdout.setEncoding("utf8");
    child.stderr.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk: string) => {
      stderr += chunk;
    });
    child.once("error", (error) => {
      spawnError = error;
    });
    child.once("close", (exitCode, signal) => {
      if (spawnError) {
        reject(spawnError);
        return;
      }
      if (exitCode === null) {
        reject(new Error(`git was terminated by signal ${signal ?? "unknown"}`));
        return;
      }
      resolve({ command, exitCode, stdout, stderr });
    });
  });
}

import { createHash, timingSafeEqual } from "node:crypto";
import { open } from "node:fs/promises";


import { access } from "node:fs/promises";
import { constants } from "node:fs";

async function fileExists(path: string): Promise<boolean> {
  try {
    await access(path, constants.F_OK);
    return true;
  } catch {
    return false;
  }
}

export default interface WriteOption {
    path: string;
    content: string;
    overwrite: boolean;
    read_hash: string;
}

/**  * Overwrites a file only when its current SHA-256 hash matches `read_hash`.  */
export default async function Write({ path, content, overwrite, read_hash, }: WriteOption): Promise<void> {
    try {
        // Usage
        if (await fileExists(path)) {
            if (!overwrite) {
                throw new Error("overwrite must be true");
            } 

            if ((typeof read_hash !== "string" || read_hash.trim() === "")) {
                throw new TypeError("read_hash is required");
            }

            console.log("File exists");
            const expectedHash = read_hash.trim().toLowerCase();
            if (!/^[a-f0-9]{64}$/.test(expectedHash)) {
                throw new TypeError("read_hash must be a SHA-256 hash encoded as 64 hexadecimal characters");
            } 

            try {
                const file = await open(path, "r+");
                try {
                    const currentContent = await file.readFile();
                    const currentHash = createHash("sha256").update(currentContent).digest("hex");
                    const hashesMatch = timingSafeEqual(Buffer.from(currentHash, "hex"), Buffer.from(expectedHash, "hex"),);
                    if (!hashesMatch) {
                        throw new Error("File has changed since it was read;  refusing to overwrite it");
                    }            
                } finally {
                    if (file) {
                        await file.close();
                    }
                }
            } catch (err) {
                throw err;
            }
        }

        const file = await open(path, "w");
        try {
            if (!file) {
                throw new Error("File handle is not available");
            }

            await file.truncate(0);
            await file.writeFile(content, { encoding: "utf8" });
        } finally {
            if (file) {
                await file.close();
            }
        }
    } catch (err) {
        throw err;
    }
}

